-- LCS 2026 Summer Playoffs realignes sur Leaguepedia + ajout de trois
-- competitions (donnees Leaguepedia du 2026-09-23, pages Data:...) :
--   * 2026 World Star Challengers Invitational (WSCI)
--   * EMEA Masters 2026 Summer LCQ (EM LCQ)
--   * EMEA Masters 2026 Summer Main Event (EM)
-- Horaires convertis en heure de Paris (Leaguepedia : PST avec DST = +9h).
-- Fichier genere a partir du wikitext Leaguepedia : les scores des matchs
-- non encore joues sont vides (SCHEDULED), a completer via l'appli.

-- ---------------------------------------------------------------------------
-- LCS 2026 Summer Playoffs (https://lol.fandom.com/wiki/LCS/2026_Season/Summer_Playoffs)
-- Double elimination a 6 avec reseed. La saison reguliere etait deja conforme,
-- mais le Lower Bracket ne l'etait pas :
--   Lower R2 (25/09) : FLY (perdant Upper R2 vs TL) vs SR (vainqueur Lower R1)
--   Lower R3 (26/09) : LYON (perdant Upper R2 vs C9) vs vainqueur Lower R2
-- (au lieu de SR vs LYON puis ? vs FLY). Les anciens 'Lower QF' / 'Lower SF'
-- sont renommes et leurs liens d'avancement recables.
-- ---------------------------------------------------------------------------
UPDATE match SET round_label = 'Lower R2',
    team1_id = (SELECT id FROM team WHERE code = 'FLY'),
    team2_id = (SELECT id FROM team WHERE code = 'SR')
WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026)
  AND bracket_side = 'LOWER' AND round_label = 'Lower QF' AND status = 'SCHEDULED';

UPDATE match SET round_label = 'Lower R3',
    team1_id = (SELECT id FROM team WHERE code = 'LYON'),
    team2_id = NULL
WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026)
  AND bracket_side = 'LOWER' AND round_label = 'Lower SF' AND status = 'SCHEDULED';

-- Vainqueur Lower R1 -> Lower R2 (slot 2)
UPDATE match SET
    next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026) AND bracket_side = 'LOWER' AND round_label = 'Lower R2'),
    next_match_slot = 2
WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026)
  AND bracket_side = 'LOWER' AND round_label = 'Lower R1';

-- Perdant Upper R2 LYON-C9 -> Lower R3 (slot 1)
UPDATE match SET
    loser_next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026) AND bracket_side = 'LOWER' AND round_label = 'Lower R3'),
    loser_next_match_slot = 1
WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026)
  AND bracket_side = 'UPPER' AND round_label = 'R2'
  AND team1_id = (SELECT id FROM team WHERE code = 'LYON') AND team2_id = (SELECT id FROM team WHERE code = 'C9');

-- Perdant Upper R2 TL-FLY -> Lower R2 (slot 1)
UPDATE match SET
    loser_next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026) AND bracket_side = 'LOWER' AND round_label = 'Lower R2'),
    loser_next_match_slot = 1
WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026)
  AND bracket_side = 'UPPER' AND round_label = 'R2'
  AND team1_id = (SELECT id FROM team WHERE code = 'TL') AND team2_id = (SELECT id FROM team WHERE code = 'FLY');

-- Vainqueur Lower R2 -> Lower R3 (slot 2)
UPDATE match SET
    next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026) AND bracket_side = 'LOWER' AND round_label = 'Lower R3'),
    next_match_slot = 2
WHERE competition_id = (SELECT id FROM competition WHERE code = 'LCS' AND season = 2026)
  AND bracket_side = 'LOWER' AND round_label = 'Lower R2';

-- ---------------------------------------------------------------------------
-- Nouvelles equipes (academies / ERL). Codes choisis pour ne pas entrer en
-- collision avec les equipes LCK/CBLOL/LCP existantes (DK, KT, DNS, VKS, CFO).
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 2026 World Star Challengers Invitational
-- (https://lol.fandom.com/wiki/2026_World_Star_Challengers_Invitational)
-- Phase de groupes : 4 groupes de 4, double round robin en BO1, modelisee en
-- saison reguliere + competition_group (classement et confrontations aller/retour).
-- Knockout Stage : elimination directe a 8 en BO5 (tirage 1ers vs 2emes, pas
-- encore effectue : equipes a determiner).
-- ---------------------------------------------------------------------------
UPDATE match SET next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Semifinal 1'), next_match_slot = 1 WHERE id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Quarterfinal 1');
UPDATE match SET next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Semifinal 1'), next_match_slot = 2 WHERE id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Quarterfinal 2');
