UPDATE match SET next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Semifinal 2'), next_match_slot = 2 WHERE id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Quarterfinal 4');
UPDATE match SET next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'GRAND_FINAL' AND round_label = 'Grand Final'), next_match_slot = 1 WHERE id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Semifinal 1');
UPDATE match SET next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'GRAND_FINAL' AND round_label = 'Grand Final'), next_match_slot = 2 WHERE id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'WSCI' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Semifinal 2');

