UPDATE match SET loser_next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'EM LCQ' AND season = 2026) AND bracket_side = 'GSL_1' AND round_label = 'Decider'), loser_next_match_slot = 1 WHERE id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'EM LCQ' AND season = 2026) AND bracket_side = 'GSL_1' AND round_label = 'Winners');
UPDATE match SET next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'EM LCQ' AND season = 2026) AND bracket_side = 'GSL_1' AND round_label = 'Decider'), next_match_slot = 2 WHERE id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'EM LCQ' AND season = 2026) AND bracket_side = 'GSL_1' AND round_label = 'Elimination');
