-- ---------------------------------------------------------------------------
-- EMEA Masters 2026 Summer Main Event
-- (https://lol.fandom.com/wiki/EMEA_Masters/2026_Season/Summer_Main_Event)
-- Swiss Stage a 32 equipes sur 7 rondes (appariements pas encore publies :
-- equipes a determiner), Knockout Matches (3 BO5 : les 3 equipes EMEA de la
-- WSCI contre les 14e-16e du Swiss), puis Playoffs a 16 en elimination directe BO5.
-- Leaguepedia ne publie pas encore d'horaire pour Knockout/Playoffs : dates
-- reprises du tableau des resultats de la page (heure inconnue), finale a la
-- date de fin annoncee (2026-10-23).
-- ---------------------------------------------------------------------------
UPDATE match SET next_match_id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'EM' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Quarterfinal 1'), next_match_slot = 1 WHERE id = (SELECT id FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'EM' AND season = 2026) AND bracket_side = 'BRACKET' AND round_label = 'Round of 16 1');
